def clean(df):
    df = df.drop_duplicates(keep=False)
    species_mapping = {'Adeile': 'Adelie', 'Gentto': 'Gentoo'}
    df['species'] = df['species'].replace(species_mapping)
    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '', regex=False).astype(float)
    valid = (df['body_mass_g'] >= 2500) & (df['body_mass_g'] <= 6500)
    df = df[valid]
    return df

def answer(df):
    return df.groupby('species')['body_mass_g'].mean().to_dict()
